     1	const { products } = require('../catalog');
     2	
     3	const tokens = (s) => s.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
     4	const index = new Map();
     5	for (const p of products) {
     6	  for (const t of tokens(p.name)) {
     7	    if (!index.has(t)) index.set(t, new Set());
     8	    index.get(t).add(p.id);
     9	  }
    10	}
    11	
    12	function search(q) {
    13	  const needle = q.trim().toLowerCase();
    14	  const exact = products.filter((p) => p.sku.toLowerCase() === needle);
    15	  const ids = new Set();
    16	  for (const t of tokens(q)) for (const id of index.get(t) ?? []) ids.add(id);
    17	  return [...exact, ...products.filter((p) => ids.has(p.id) && !exact.includes(p))];
    18	}
    19	
    20	module.exports = { search };

